// Vercel deployment trigger
import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  LayoutDashboard, UserCog, Building, Users, CreditCard, User, FileCheck,
  Building2, ShieldAlert, Sparkles, MapPin, Search, Plus, ShieldCheck, 
  Lock, Unlock, PhoneCall, Award, TrendingUp, Calendar, AlertTriangle, 
  ArrowUpRight, DollarSign, CheckCircle2, FileText, Bot, RefreshCw, Send, 
  Check, Phone, MessageSquare, UserCheck, ChevronRight, Layers, FileSpreadsheet,
  Download, Printer, Filter, Star, Clock, AlertOctagon, UserX, Radio, Cpu, 
  CheckSquare, XCircle, RotateCw, Play, MessageCircle, Tag, UserPlus, 
  CheckCircle, Sliders, Zap, Shield, AlertCircle, Briefcase, Key, Repeat, 
  CheckSquare2, Receipt, Target, Hash, LifeBuoy, FileCode, ArrowRightLeft, ArrowRight, UserCheck2, X,
  Compass, QrCode, Share2, Layers3, Activity, Eye, EyeOff, ThumbsUp, ThumbsDown,
  Upload, FileUp, FileDown, Table, FileSignature, Scale, PenTool, ReceiptText, Calculator, Landmark,
  Grid, List, Columns, Edit3, Trash2, Layers2, Navigation, Map as MapIcon, PieChart, BarChart2,
  GitMerge, ArrowDown, Sun, Moon, Menu, LogOut, BookmarkCheck, Camera, Image as ImageIcon, SearchCode, Globe, ExternalLink
} from 'lucide-react';

export const extractAllIdentifiers = (item: any): Set<string> => {
  const ids = new Set<string>();
  if (!item) return ids;

  const data = item.originalData || item;

  [
    item.id,
    data.id,
    data._id,
    data.property_code,
    data.code,
    data.project_id,
    data.project_code,
    data.lead_number,
    data.customer_number,
    data.name
  ].forEach(val => {
    if (val && typeof val === 'string' && val.trim()) {
      const trimmed = val.trim();
      ids.add(trimmed);
      ids.add(trimmed.toLowerCase());
      ids.add(trimmed.toUpperCase());
    }
  });

  const titlesToProcess = [
    item.title,
    data.title,
    data.property_title,
    data.project_title,
    data.project_name,
    data.name
  ];

  titlesToProcess.forEach(rawTitle => {
    if (rawTitle && typeof rawTitle === 'string' && rawTitle.trim()) {
      const t = rawTitle.trim();
      ids.add(t.toLowerCase());
      const cleanT = t.replace(/\s*\([^)]*\)/g, '').trim().toLowerCase();
      if (cleanT) ids.add(cleanT);
      const match = t.match(/\(([^)]+)\)/);
      if (match && match[1]) {
        ids.add(match[1].trim().toLowerCase());
        ids.add(match[1].trim().toUpperCase());
      }
    }
  });

  return ids;
};

export const isItemInRecycledSet = (targetItem: any, recycledSet: Set<string>): boolean => {
  if (!targetItem || !recycledSet || recycledSet.size === 0) return false;
  const targetIds = extractAllIdentifiers(targetItem);
  for (const id of targetIds) {
    if (recycledSet.has(id)) return true;
  }
  return false;
};

import { ProfileView } from './components/ProfileView';
import { RecycleBinView } from './components/RecycleBinView';
